mapper.insert:
INSERT INTO ${tableName} (SRL_NO, ALS, FORM_NO, ALPH, GNDR, LVL, NO, IV)
VALUES (
       (SELECT max_seq FROM (SELECT MAX(SRL_NO) + 1 AS max_seq FROM ${tableName}) AS t)
     , #{vo.als}
     , IFNULL(NULLIF(#{vo.formNo}, ''), 1)
     , IFNULL(NULLIF(#{vo.alph}, ''), 0)
     , #{vo.gender}
     , #{vo.lvl}
     , (SELECT no FROM pokedex WHERE name = #{vo.name})
     , #{vo.iv}
)

mapper.update:
UPDATE ${tableName}
   SET ALS     = #{vo.als}
     , FORM_NO = IFNULL(NULLIF(#{vo.formNo}, ''), 1)
     , ALPH    = IFNULL(NULLIF(#{vo.alph}, ''), 0)
     , GNDR    = #{vo.gender}
     , LVL     = #{vo.lvl}
     , NO      = (SELECT no FROM pokedex WHERE name = #{vo.name})
     , IV      = #{vo.iv}
 WHERE SRL_NO = #{vo.srlNo}

UPDATE ${tableName}
   SET SRL_NO = SRL_NO - 1
 WHERE SRL_NO > #{vo.srlNo}
 ORDER BY SRL_NO ASC

UPDATE ${tableName}
   SET SRL_NO = SRL_NO + 1
 WHERE SRL_NO >= #{vo.srlNo}
 ORDER BY SRL_NO DESC

